def get_student_info(
    xml_data: str, username: str, password: str
) -> Dict[str, str] | None:
    out = exec_cmd(['node', safe_path, xml_data, username, password])[1]
    try:
        name, age, citizenship = out.splitlines()
        return {
            ""name"": name,
            ""age"": age,
            ""citizenship"": citizenship,
        }
    except:
        return None


